package mz.bam.seeky.android;
import android.app.*;import android.content.*;import android.graphics.Typeface;import android.os.*;import android.widget.*;import java.util.concurrent.*;
/** Small shared native forms. Data work stays on a single bounded background queue. */
final class PlusUi {
 /** Ícone de funcionalidade dentro de um quadrado arredondado tingido — o mesmo estilo do painel Mais. */
 static android.view.View iconTile(Context c,String symbol,AppPalette colors){FrameLayout tile=new FrameLayout(c);tile.setBackground(ThemeStyle.tile(c,colors,40));tile.addView(new Icons(c,symbol,colors.accent),new FrameLayout.LayoutParams(dp(c,22),dp(c,22),android.view.Gravity.CENTER));tile.setImportantForAccessibility(android.view.View.IMPORTANT_FOR_ACCESSIBILITY_NO);return tile;}
 /** Botão de voltar com ícone, área de toque de 44 dp e descrição para leitores de ecrã. */
 static android.view.View backButton(Activity a,AppPalette colors,Runnable back){FrameLayout b=new FrameLayout(a);b.addView(new Icons(a,"back",colors.accent),new FrameLayout.LayoutParams(dp(a,23),dp(a,23),android.view.Gravity.CENTER));android.graphics.drawable.GradientDrawable bg=new android.graphics.drawable.GradientDrawable();bg.setColor(colors.tint);bg.setCornerRadius(dp(a,14));b.setBackground(bg);b.setContentDescription(AppLanguage.text(a,"Voltar"));b.setOnClickListener(v->back.run());Motion.touch(b);return b;}
 static final ThreadPoolExecutor WORK=new ThreadPoolExecutor(1,1,30,TimeUnit.SECONDS,new LinkedBlockingQueue<Runnable>(64),r->{Thread t=new Thread(r,"seeky-tools");t.setDaemon(true);return t;});static{WORK.allowCoreThreadTimeOut(true);}static final ThreadPoolExecutor LONG=new ThreadPoolExecutor(1,1,30,TimeUnit.SECONDS,new LinkedBlockingQueue<Runnable>(32),r->{Thread t=new Thread(r,"seeky-long-tools");t.setDaemon(true);return t;});static{LONG.allowCoreThreadTimeOut(true);}static final Handler MAIN=new Handler(Looper.getMainLooper());
 interface Task{void run()throws Exception;}
 static int dp(Context c,float n){return(int)(n*c.getResources().getDisplayMetrics().density+.5f);}
 static LinearLayout column(Context c){LinearLayout l=new LinearLayout(c);l.setOrientation(1);l.setPadding(dp(c,12),dp(c,6),dp(c,12),dp(c,6));return l;}
 static TextView text(Context c,String s,int sp){TextView v=new TextView(c);v.setText(AppLanguage.text(c,s));v.setTextColor(AppPalette.of(c).ink);v.setTextSize(sp);v.setPadding(0,dp(c,7),0,dp(c,7));return v;}
 static EditText input(Context c,String label,String value,int max){EditText e=new EditText(c);e.setTextColor(AppPalette.of(c).ink);e.setHintTextColor(AppPalette.of(c).muted);e.setHint(AppLanguage.text(c,label));e.setText(value);e.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(max)});e.setMinHeight(dp(c,48));return e;}
 static void post(Activity a,Runnable r){MAIN.post(()->{if(!a.isFinishing()&&!a.isDestroyed())r.run();});}
 static void run(Activity a,Task work){final long epoch=WorkspaceEpoch.value;try{WORK.execute(()->{if(epoch!=WorkspaceEpoch.value)return;try{work.run();}catch(Exception|OutOfMemoryError e){AppDiagnostics.record(a.getApplicationContext(),"reading-tools",e);post(a,()->error(a,e));}});}catch(RejectedExecutionException e){post(a,()->toast(a,"Aguarde a operação actual."));}}
 static void longRun(Activity a,Task task){final long epoch=WorkspaceEpoch.value;try{LONG.execute(()->{if(epoch!=WorkspaceEpoch.value)return;try{task.run();}catch(Exception|OutOfMemoryError e){AppDiagnostics.record(a.getApplicationContext(),"long-tools",e);post(a,()->error(a,e));}});}catch(RejectedExecutionException e){toast(a,"Aguarde a operação actual.");}}
 static void error(Activity a,Throwable e){new UiDialog.Builder(a).setTitle("Não foi possível concluir").setMessage(e instanceof OutOfMemoryError?"Pouca memória. Feche outro documento e tente novamente.":e.getMessage()==null?"Operação indisponível.":e.getMessage()).setPositiveButton("Fechar",null).show();}
 static void toast(Context c,String s){Toast.makeText(c,AppLanguage.text(c,s),Toast.LENGTH_LONG).show();}
 static void performance(Activity a){int current=a.getSharedPreferences("seeky",0).getInt("performance_mode",0);new UiDialog.Builder(a).setTitle("Desempenho").setSingleChoiceItems(new String[]{"Automático","Leve","Completo"},current,(d,n)->{PerformanceMode.choose(a,n);d.dismiss();toast(a,PerformanceMode.light(a)?"Modo leve activo. Reabra os documentos para aplicar os limites.":"Modo completo activo. Reabra os documentos para aplicar os limites.");}).setNegativeButton("Fechar",null).show();}
 static void dictionary(Activity a){UiPanel p=new UiPanel(a,"Dicionário de pronúncia",null,"speaker");for(PronunciationRules.Rule r:VoiceText.rules(a))p.action("edit",r.word+" → "+r.say,null,false,()->editRule(a,r.word,r.say));p.action("add","Adicionar pronúncia",null,false,()->editRule(a,"",""));p.show();}
 static void editRule(Activity a,String old,String say){LinearLayout form=column(a);EditText word=input(a,"Palavra ou sigla",old,80),spoken=input(a,"Como deve ser lida",say,120);form.addView(word);form.addView(spoken);UiDialog dialog=new UiDialog.Builder(a).setTitle("Pronúncia pessoal").setView(form).setPositiveButton("Guardar",null).setNeutralButton(old.isEmpty()?null:"Eliminar",(d,w)->{if(!old.isEmpty()){saveRule(a,old,null);dictionary(a);}}).setNegativeButton("Fechar",null).create();dialog.show();dialog.getButton(-1).setOnClickListener(v->{try{PronunciationRules.Rule rule=new PronunciationRules.Rule(word.getText().toString(),spoken.getText().toString());saveRule(a,old,rule);dialog.dismiss();dictionary(a);}catch(Exception e){toast(a,e.getMessage());}});}
 static void saveRule(Context c,String old,PronunciationRules.Rule replacement){org.json.JSONArray values=new org.json.JSONArray();try{for(PronunciationRules.Rule r:VoiceText.rules(c))if(!r.word.equalsIgnoreCase(old)&&(replacement==null||!r.word.equalsIgnoreCase(replacement.word)))values.put(new org.json.JSONObject().put("word",r.word).put("say",r.say));if(replacement!=null){if(values.length()>=100)throw new IllegalArgumentException("O dicionário já tem 100 entradas.");values.put(new org.json.JSONObject().put("word",replacement.word).put("say",replacement.say));}c.getSharedPreferences(VoiceText.PREF,0).edit().putString("rules",values.toString()).apply();}catch(org.json.JSONException e){throw new IllegalArgumentException(e);}}
 private PlusUi(){}
}
